import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, positionLocal, length as tslLength, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(THREE, hex) {
  const c = new THREE.Color(hex);
  return vec3(c.r, c.g, c.b);
}

function roundedRectShape(THREE, w, h, r) {
  const shape = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x, y + r);
  shape.lineTo(x, y + h - r);
  shape.quadraticCurveTo(x, y + h, x + r, y + h);
  shape.lineTo(x + w - r, y + h);
  shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
  shape.lineTo(x + w, y + r);
  shape.quadraticCurveTo(x + w, y, x + w - r, y);
  shape.lineTo(x + r, y);
  shape.quadraticCurveTo(x, y, x, y + r);
  return shape;
}

function disposeDeep(obj) {
  if (!obj) return;
  obj.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        if (m.map) m.map.dispose?.();
        m.dispose?.();
      });
    }
  });
}

function setColorDeep(obj, hex) {
  if (!obj) return;
  obj.traverse((child) => {
    if (child.material && child.material.color) {
      child.material.color.set(hex);
      child.material.needsUpdate = true;
    }
  });
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config?.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1b1b23' }, { at: 1, hex: '#101015' }],
  };
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';
  const INACTIVE = '#a6adba';
  const GRAD_TOP = colors.gradientStops?.[0]?.hex ?? '#1b1b23';
  const GRAD_BOTTOM = colors.gradientStops?.[1]?.hex ?? '#101015';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'HOME', role: 'nav-active' },
    { text: 'FEATURES', role: 'nav-item' },
    { text: 'COLLECTION', role: 'nav-item' },
    { text: 'PRICING', role: 'nav-item' },
    { text: 'JOURNAL', role: 'nav-item' },
  ];

  const navIdMap = {
    HOME: 'hub-home',
    FEATURES: 'hub-features',
    COLLECTION: 'hub-collection',
    PRICING: 'hub-pricing',
    JOURNAL: 'hub-journal',
  };

  const root = new THREE.Group();
  root.name = 'nav-dock';

  const RAIL_W = 3.6;
  const RAIL_H = 0.5;
  const RAIL_R = 0.1;
  const RAIL_DEPTH = 0.08;

  // ---- Contact shadow plane ----
  const shadowGeo = new THREE.PlaneGeometry(RAIL_W * 1.08, RAIL_H * 1.2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const radial = tslLength(uv().sub(vec2(0.5, 0.5)).mul(vec2(1.0, 1.6)));
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = smoothstep(0.55, 0.0, radial).mul(0.4);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.06, -0.02);
  root.add(shadowMesh);

  // ---- Machined rail ----
  const shape = roundedRectShape(THREE, RAIL_W, RAIL_H, RAIL_R);
  const railGeo = new THREE.ExtrudeGeometry(shape, {
    depth: RAIL_DEPTH,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 12,
    steps: 1,
  });
  railGeo.translate(0, 0, -RAIL_DEPTH / 2);

  const railMat = new MeshPhysicalNodeMaterial();
  const topColor = hexToVec3(THREE, GRAD_TOP);
  const bottomColor = hexToVec3(THREE, GRAD_BOTTOM);
  const t = smoothstep(-RAIL_H / 2, RAIL_H / 2, positionLocal.y);
  railMat.colorNode = mix(bottomColor, topColor, t);
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.clearcoatRoughness = 0.35;
  if ('anisotropy' in railMat) {
    railMat.anisotropy = 0.6;
    railMat.anisotropyRotation = 0.0;
  }

  const railGroup = new THREE.Group();
  const railMesh = new THREE.Mesh(railGeo, railMat);
  railGroup.add(railMesh);
  railGroup.position.z = 0.15;
  root.add(railGroup);

  // node-local rim + accent lights (rail is a metal PBR subject; needs local light to read form)
  const rimLight = new THREE.PointLight(new THREE.Color(PAPER), 0.7, 6);
  rimLight.position.set(-1.5, 1.2, 2.2);
  root.add(rimLight);
  const accentGlow = new THREE.PointLight(new THREE.Color(ACCENT), 0.5, 3);
  accentGlow.position.set(0, -0.15, 0.6);
  root.add(accentGlow);

  // ---- Entries ----
  const COUNT = 5;
  const SPACING = 0.68;
  const CELL_W = 0.6;
  const CELL_H = 0.34;
  const startX = -((COUNT - 1) * SPACING) / 2;

  const entryRefs = [];
  const hitMeshes = [];
  let activeIndex = 0;

  for (let i = 0; i < COUNT; i++) {
    const item = items[i] ?? { text: '', role: 'nav-item' };
    const label = String(item.text ?? '').toUpperCase();
    const isActive = item.role === 'nav-active';
    if (isActive) activeIndex = i;

    const cx = startX + i * SPACING;

    const cellGroup = new THREE.Group();
    cellGroup.position.set(cx, 0, RAIL_DEPTH / 2 + 0.16);
    railGroup.add(cellGroup);

    const hitGeo = new THREE.PlaneGeometry(CELL_W, CELL_H);
    const hitMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.001, depthWrite: false });
    const hitMesh = new THREE.Mesh(hitGeo, hitMat);
    hitMesh.userData.isNavHit = true;
    hitMesh.userData.navIndex = i;
    hitMesh.userData.navId = navIdMap[label] ?? `hub-${label.toLowerCase()}`;
    cellGroup.add(hitMesh);
    hitMeshes.push(hitMesh);

    const textColor = isActive ? PAPER : INACTIVE;
    const textObj = ctx.fontAtlas.createText(label, {
      fontSize: 13,
      color: textColor,
      align: 'center',
      letterSpacingPx: 0.08 * 13,
    });
    textObj.position.set(0, 0.0, 0.01);
    cellGroup.add(textObj);

    entryRefs.push({
      cellGroup,
      textObj,
      hitMesh,
      navId: hitMesh.userData.navId,
      hoverColor: INACTIVE,
      pressed: false,
    });
  }

  // ---- Active underline bar ----
  const barGeo = new THREE.PlaneGeometry(0.28, 0.025);
  const barMat = new MeshStandardNodeMaterial();
  const accentVec = hexToVec3(THREE, ACCENT);
  barMat.colorNode = accentVec;
  barMat.emissiveNode = accentVec.mul(1.8);
  barMat.roughness = 0.6;
  barMat.metalness = 0.0;
  const bar = new THREE.Mesh(barGeo, barMat);
  bar.position.set(startX + activeIndex * SPACING, -0.15, RAIL_DEPTH / 2 + 0.18);
  railGroup.add(bar);

  // ---- Mount animation: rise-in ----
  root.position.y -= 0.4;
  const mountTween = gsap.to(root.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });

  const timelines = [mountTween];

  function moveUnderline(index) {
    const targetX = startX + index * SPACING;
    const overshootX = targetX + (targetX >= bar.position.x ? 0.02 : -0.02) * 1.04;
    const tl = gsap.timeline();
    tl.to(bar.position, { x: overshootX, duration: 0.18, ease: 'power3.out' });
    tl.to(bar.position, { x: targetX, duration: 0.08, ease: 'power1.inOut' });
    timelines.push(tl);
  }

  function setActive(index) {
    if (index === activeIndex) return;
    const prev = entryRefs[activeIndex];
    const next = entryRefs[index];
    if (prev) {
      const tw = gsap.to({ v: 0 }, {
        v: 1,
        duration: 0.16,
        ease: 'power2.out',
        onUpdate() {
          setColorDeep(prev.textObj, INACTIVE);
        },
      });
      timelines.push(tw);
    }
    if (next) {
      setColorDeep(next.textObj, PAPER);
    }
    activeIndex = index;
    moveUnderline(index);
  }

  function findEntry(navIndex) {
    return entryRefs[navIndex];
  }

  // ---- Interaction handlers ----
  let hoveredIndex = -1;

  root.userData.handlers = {
    onPointerMove(event) {
      const obj = event?.object;
      const idx = obj?.userData?.navIndex;
      if (idx === undefined || idx === null) {
        if (hoveredIndex >= 0 && hoveredIndex !== activeIndex) {
          const entry = findEntry(hoveredIndex);
          if (entry) {
            const tw = gsap.to({ v: 0 }, {
              v: 1,
              duration: 0.16,
              ease: 'power2.out',
              onUpdate() { setColorDeep(entry.textObj, INACTIVE); },
            });
            timelines.push(tw);
          }
        }
        hoveredIndex = -1;
        return;
      }
      if (idx === hoveredIndex || idx === activeIndex) return;
      if (hoveredIndex >= 0 && hoveredIndex !== activeIndex) {
        const prevEntry = findEntry(hoveredIndex);
        if (prevEntry) setColorDeep(prevEntry.textObj, INACTIVE);
      }
      hoveredIndex = idx;
      const entry = findEntry(idx);
      if (entry) {
        const tw = gsap.to({ v: 0 }, {
          v: 1,
          duration: 0.16,
          ease: 'power2.out',
          onUpdate() { setColorDeep(entry.textObj, PAPER === INACTIVE ? PAPER : '#e8ecf2'); },
        });
        timelines.push(tw);
      }
    },

    onPointerDown(event) {
      const obj = event?.object;
      const idx = obj?.userData?.navIndex;
      if (idx === undefined || idx === null) return;
      const entry = findEntry(idx);
      if (!entry || entry.pressed) return;
      entry.pressed = true;
      const tw = gsap.to(entry.cellGroup.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      });
      const tz = gsap.to(entry.cellGroup.position, {
        z: entry.cellGroup.position.z - 0.03,
        duration: 0.12,
        ease: 'power2.out',
      });
      timelines.push(tw, tz);
    },

    onPointerUp(event) {
      const obj = event?.object;
      const idx = obj?.userData?.navIndex;
      entryRefs.forEach((entry, i) => {
        if (!entry.pressed) return;
        entry.pressed = false;
        const tw = gsap.to(entry.cellGroup.scale, {
          x: 1, y: 1, z: 1,
          duration: 0.12,
          ease: 'back.out(1.7)',
        });
        const tz = gsap.to(entry.cellGroup.position, {
          z: RAIL_DEPTH / 2 + 0.16,
          duration: 0.12,
          ease: 'power2.out',
        });
        timelines.push(tw, tz);
      });
      if (idx !== undefined && idx !== null) {
        setActive(idx);
        const navId = entryRefs[idx]?.navId;
        if (navId) ctx.emit('navigate', { to: navId });
      }
    },

    onClick(event) {
      const obj = event?.object;
      const idx = obj?.userData?.navIndex;
      if (idx === undefined || idx === null) return;
      setActive(idx);
      const navId = entryRefs[idx]?.navId;
      if (navId) ctx.emit('navigate', { to: navId });
    },
  };

  root.userData.cleanup = function cleanup() {
    timelines.forEach((tl) => tl && tl.kill && tl.kill());
    if (mountTween && mountTween.kill) mountTween.kill();
    disposeDeep(root);
  };

  return root;
}
